import java.util.Scanner;

public class Main {
    static final long MOD = 1000000007L;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long p = sc.nextLong();
        long k = sc.nextLong();
        long q = k;

        if (k == 0) {
            System.out.println(computePower(p, p - 1));
            return;
        }
        if (k == 1) {
            System.out.println(computePower(p, p));
            return;
        }

        int n = 1;
        while (q != 1) {
            q = (q * k) % p;
            n++;
        }
        System.out.println(computePower(p, (p - 1) / n));
    }

    static long computePower(long base, long exponent) {
        if (exponent == 0)
            return 1;
        long half = computePower(base, exponent / 2);
        long result = (half * half) % MOD;
        if (exponent % 2 == 1) {
            result = (result * base) % MOD;
        }
        return result;
    }
}
